import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const root=path.resolve(path.dirname(new URL(import.meta.url).pathname),'..');
const data=await import('data:text/javascript;base64,'+Buffer.from(fs.readFileSync(path.join(root,'data.js'))).toString('base64'));
const noop=()=>{};
const node=()=>({innerHTML:'',textContent:'',style:{setProperty:noop},classList:{add:noop,remove:noop,toggle:noop},dataset:{},addEventListener:noop,querySelector:()=>node(),querySelectorAll:()=>[],appendChild:noop,before:noop,prepend:noop,insertAdjacentHTML:noop,focus:noop,remove:noop,getAttribute:()=>null,setAttribute:noop,click:noop});
const nodes=new Map();
const storage=new Map();let callbacks=[],intervals=[];const writes=[];
const ctx=vm.createContext({...data,assert,console,Date,Math,JSON,Map,Set,Number,Object,Array,String,Infinity,URL,Blob,structuredClone,
 document:{querySelector:q=>{if(!nodes.has(q))nodes.set(q,node());return nodes.get(q)},querySelectorAll:()=>[],body:node(),addEventListener:noop,createElement:()=>node(),createTreeWalker:()=>({nextNode:()=>null}),hidden:false},
 navigator:{onLine:true,geolocation:{getCurrentPosition(fn){ctx.gpsCallback=fn},watchPosition(fn){ctx.gpsCallback=fn;return 1},clearWatch:noop}},
 window:{addEventListener:noop,matchMedia:()=>({matches:false}),navigator:{},location:{},innerWidth:390},location:{reload:noop},
 MutationObserver:class{observe(){}},NodeFilter:{SHOW_TEXT:4},performance:{now:()=>Date.now()},
 localStorage:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>{storage.set(k,v);writes.push([k,v])},removeItem:k=>storage.delete(k)},
 setTimeout:(fn,delay)=>{callbacks.push({fn,delay});return callbacks.length},clearTimeout:noop,setInterval:(fn,delay)=>{intervals.push(fn);return intervals.length},clearInterval:noop,
 requestAnimationFrame:noop,cancelAnimationFrame:noop,confirm:()=>true});
let src=fs.readFileSync(path.join(root,'app.js'),'utf8').replace(/^import[^\n]+\n/,'');
src=src.slice(0,src.lastIndexOf('state=load();restoreSession();'));
vm.runInContext(src,ctx);
const run=s=>vm.runInContext(`{${s}}`,ctx);
run(`globalThis.originalOpenCombat=openCombat;globalThis.originalOpenBuilding=openBuilding;globalThis.originalRenderSocial=renderSocial;render=()=>{};renderShell=()=>{};openBuilding=()=>{};openCombat=()=>{};closeModal=()=>{};playSfx=()=>{};haptic=()=>{};setAmbient=()=>{};newGame('Tester','knight');state.tutorial.introSeen=true;state.settings.masterSound=false;state.settings.haptics=false;state.quests.active=[];`);
const base=run('JSON.stringify(state)');
let count=0;
function fresh(){run(`state=normalizeState(${base});state.quests.active=[];combat=null;dungeonRun=null;battleResult=null;saveDepth=0;SAVE_KEY=REAL_SAVE_KEY;lastAcceptedFix=null;lastGpsTick=0;gpsWatch=null;`);callbacks=[];writes.length=0;ctx.document.querySelectorAll=()=>[];}
function test(name,fn){fresh();fn();count++;console.log('PASS',name)}
test('illustrated city map routes its buildings to their interiors',()=>{
 assert.ok(fs.existsSync(path.join(root,'assets/backgrounds/city-map-3995.webp')));
 const el=node(),tavern={dataset:{building:'tavern'}};
 el.querySelectorAll=selector=>selector==='[data-building]:not(:disabled)'?[tavern]:[];
 run('globalThis.lastCityOpen=null;openBuilding=(id,view)=>{globalThis.lastCityOpen=[id,view]};');
 ctx.renderTown(el);
 assert.equal((el.innerHTML.match(/class="city-map-hotspot /g)||[]).length,6);
 for(const id of ['tavern','shop','smith','alchemist','auction','guild'])assert.ok(el.innerHTML.includes(`data-building="${id}"`),id);
 assert.ok(el.innerHTML.includes('city-map-3995.webp'));
 tavern.onclick();
 assert.equal(JSON.stringify(ctx.lastCityOpen),JSON.stringify(['tavern','scene']));
});
test('full backpack purchase preserves gold and inventory',()=>run(`state.player.inventoryCapacity=inventoryUsedSlots();state.player.gold=100;const before=JSON.stringify(state.player);buyItem('shortSword','shop',20);assert.equal(JSON.stringify(state.player),before);`));
test('stackable purchase uses existing stack in full bag',()=>run(`state.player.inventoryCapacity=inventoryUsedSlots();state.player.gold=100;const q=countItem('potion');buyItem('potion','shop',20);assert.equal(countItem('potion'),q+1);assert.equal(state.player.gold,80);`));
test('craft rejects output when no slot will be freed',()=>run(`ensureAlchemyState();state.alchemy.recipeUses.manaPotion=2;state.player.inventoryCapacity=inventoryUsedSlots();state.player.gold=10000;state.player.inventory.find(i=>i.id==='herb').qty=10;state.player.inventory.push({id:'crystal',qty:10});state.player.inventoryCapacity=inventoryUsedSlots();const before=JSON.stringify(state.player);craftRecipe('manaPotion');assert.equal(JSON.stringify(state.player),before);`));
test('craft accepts slot freed by consumed ingredient',()=>run(`ensureAlchemyState();state.alchemy.recipeUses.manaPotion=2;state.player.gold=10000;state.player.inventory.find(i=>i.id==='herb').qty=1;state.player.inventory.push({id:'crystal',qty:1});state.player.inventoryCapacity=inventoryUsedSlots();craftRecipe('manaPotion');assert.equal(countItem('manaPotion'),1);assert.equal(countItem('herb'),0);assert.equal(countItem('crystal'),0);assert.equal(state.alchemy.recipeUses.manaPotion,1);`));
test('unsocket does not charge or remove rune with full bag',()=>run(`const w=state.player.inventory.find(i=>i.uid);w.rune='runePower';state.player.gold=10000;state.player.inventoryCapacity=inventoryUsedSlots();const before=JSON.stringify(state.player);unsocketRune(w.uid);assert.equal(JSON.stringify(state.player),before);`));
test('invalid item is not added',()=>run(`const before=JSON.stringify(state.player.inventory);assert.equal(addItem(null),0);assert.equal(addItem('missing'),0);assert.equal(JSON.stringify(state.player.inventory),before);`));
test('mana potion restores actual deficit and consumes a turn',()=>run(`state.player.inventory.push({id:'manaPotion',qty:2});state.player.mana=0;startCombat({id:'test',template:'slime',type:'monster',synthetic:true,variant:'normal',elite:false});combatPotion('manaPotion');assert.equal(state.player.mana,45);assert.equal(countItem('manaPotion'),1);assert.equal(combat.phase,'enemyDelay');`));
test('full health potion is not consumed and does not advance turn',()=>run(`startCombat({id:'test',template:'slime',type:'monster',synthetic:true,variant:'normal',elite:false});const q=countItem('potion');combatPotion('potion');assert.equal(countItem('potion'),q);assert.equal(combat.phase,'player');`));
test('strong potion restores health',()=>run(`state.player.hp=10;state.player.inventory.push({id:'strongPotion',qty:1});startCombat({id:'test',template:'slime',type:'monster',synthetic:true,variant:'normal',elite:false});combatPotion('strongPotion');assert.equal(state.player.hp,140);assert.equal(countItem('strongPotion'),0);`));
test('purchase stores only final transaction snapshot',()=>{run(`state.player.gold=100;buyItem('potion','shop',20);`);const mainWrites=writes.filter(([k])=>k==='time4heroes_build_390');assert.equal(mainWrites.length,1);const snap=JSON.parse(mainWrites[0][1]);assert.equal(snap.player.gold,80);assert.equal(snap.player.inventory.find(i=>i.id==='potion').qty,4)});
test('combat snapshot retains phase and reconnects world entity',()=>run(`const e=state.world.entities.find(e=>e.type==='monster');startCombat(e);combat.hp=20;queueEnemyTurn();state=JSON.parse(localStorage.getItem(SAVE_KEY));combat=null;restoreSession();assert.equal(combat.hp,20);assert.equal(combat.phase,'enemyDelay');assert.equal(combat.entity,state.world.entities.find(e=>e.id===combat.entity.id));`));
test('resume after enemy result does not apply another hit',()=>{run(`startCombat({id:'test',template:'slime',type:'monster',synthetic:true,variant:'normal',elite:false});combat.phase='enemyResult';state.player.hp=80;save();state=JSON.parse(localStorage.getItem(SAVE_KEY));restoreSession();resumeSession();`);const cb=callbacks.filter(c=>c.delay===350).at(-1);assert.ok(cb);cb.fn();run(`assert.equal(state.player.hp,80);assert.equal(combat.phase,'player');`)});
test('dungeon grid and deadline survive reload',()=>run(`const d=DUNGEONS[0];state.player.level=d.min;const a=dungeonAccess(d.id);a.guardianDefeated=true;state.player.dungeons.push(d.id);openDungeonCrawler=()=>{};startDungeon(d);const grid=JSON.stringify(dungeonRun.grid),deadline=dungeonRun.deadline;state=JSON.parse(localStorage.getItem(SAVE_KEY));dungeonRun=null;restoreSession();assert.equal(JSON.stringify(dungeonRun.grid),grid);assert.equal(dungeonRun.deadline,deadline);assert.equal(dungeonAccess(d.id).attempts,1);`));
test('reward screen survives reload without awarding XP twice',()=>run(`showBattleVictory=()=>{};startCombat({id:'test',template:'slime',type:'monster',synthetic:true,variant:'normal',elite:false});winCombat();const xp=state.player.xp,gold=state.player.gold;assert.ok(battleResult);state=JSON.parse(localStorage.getItem(SAVE_KEY));restoreSession();resumeSession();assert.equal(state.player.xp,xp);assert.equal(state.player.gold,gold);assert.ok(battleResult);assert.equal(combat,null);`));
test('GPS rejects poor accuracy before moving player',()=>{run(`currentTab='hero';toggleGps();`);const before=run('JSON.stringify(state.player.position)');ctx.gpsCallback({coords:{latitude:51,longitude:22,accuracy:150},timestamp:Date.now()});assert.equal(run('JSON.stringify(state.player.position)'),before)});
test('GPS rejects stale fix before moving player',()=>{run(`currentTab='hero';toggleGps();`);const before=run('JSON.stringify(state.player.position)');ctx.gpsCallback({coords:{latitude:51,longitude:22,accuracy:10},timestamp:Date.now()-60000});assert.equal(run('JSON.stringify(state.player.position)'),before)});
test('GPS accepts current accurate fix and rejects sudden teleport',()=>{run(`currentTab='hero';toggleGps();`);ctx.gpsCallback({coords:{latitude:51,longitude:22,accuracy:10},timestamp:Date.now()});run(`assert.equal(state.player.position.lat,51);assert.equal(gpsInteractionReady(),true);lastGpsTick=0;`);ctx.gpsCallback({coords:{latitude:52,longitude:23,accuracy:10},timestamp:Date.now()});run(`assert.equal(state.player.position.lat,51);`)});
test('old position cannot authorize GPS interaction',()=>run(`state.player.position={gps:true,accuracy:5,receivedAt:Date.now()-60000};gpsWatch=1;assert.equal(gpsInteractionReady(),false);`));
test('demo movement is blocked in primary save',()=>run(`const pos=JSON.stringify(state.player.position);moveDemo(20,0);assert.equal(JSON.stringify(state.player.position),pos);`));
test('separate sandbox snapshot cannot overwrite primary',()=>{run(`state.player.gold=123;save();switchPlayMode();`);const real=JSON.parse(storage.get('time4heroes_build_390')),demo=JSON.parse(storage.get('time4heroes_build_390_sandbox'));assert.equal(real.playMode,'gps');assert.equal(demo.playMode,'sandbox');assert.equal(real.player.gold,demo.player.gold);run(`SAVE_KEY=DEMO_SAVE_KEY;state=JSON.parse(localStorage.getItem(DEMO_SAVE_KEY));state.player.gold=999;save();`);assert.equal(JSON.parse(storage.get('time4heroes_build_390')).player.gold,123)});
test('combat UI groups potions under Healing command',()=>run(`state.player.inventory.push({id:'manaPotion',qty:1},{id:'strongPotion',qty:1});startCombat({id:'test',template:'slime',type:'monster',synthetic:true,variant:'normal',elite:false});originalOpenCombat();assert.ok(app.innerHTML.includes('data-command="heal"'));assert.ok(!app.innerHTML.includes('data-combat-potion="manaPotion"'));combat.menu='heal';originalOpenCombat();assert.ok(app.innerHTML.includes('data-combat-potion="manaPotion"'));assert.ok(app.innerHTML.includes('data-combat-potion="strongPotion"'));assert.ok(app.innerHTML.includes('Dziennik walki'));`));
test('combat loadout keeps at most four learned skills',()=>run(`state.player.skills=SKILLS.knight.slice(0,6).map(s=>s.id);delete state.player.activeSkills;ensureCombatSkillLoadout();assert.equal(state.player.activeSkills.length,4);const fifth=state.player.skills[4];toggleCombatSkill(fifth);assert.ok(!state.player.activeSkills.includes(fifth));toggleCombatSkill(state.player.activeSkills[0]);toggleCombatSkill(fifth);assert.ok(state.player.activeSkills.includes(fifth));assert.equal(state.player.activeSkills.length,4);`));
test('combat fight submenu renders only selected active skills',()=>run(`state.player.skills=SKILLS.knight.slice(0,6).map(s=>s.id);state.player.activeSkills=state.player.skills.slice(1,5);startCombat({id:'test',template:'slime',type:'monster',synthetic:true,variant:'normal',elite:false});combat.menu='fight';originalOpenCombat();for(const id of state.player.activeSkills)assert.ok(app.innerHTML.includes('data-skill="'+id+'"'));assert.ok(!app.innerHTML.includes('data-skill="'+state.player.skills[0]+'"'));assert.ok(!app.innerHTML.includes('data-skill="'+state.player.skills[5]+'"'));`));
test('all item definitions have individual art',()=>{for(const id of vm.runInContext('Object.keys(ITEMS)',ctx))assert.ok(fs.existsSync(path.join(root,'assets/item-art',id+'.webp')),id)});
test('class gear provides four tiers for every class',()=>{for(const cls of Object.keys(data.CLASSES)){const gear=Object.values(data.ITEMS).filter(d=>d.classGear&&d.classes?.includes(cls));for(const lvl of [12,28,45,70])assert.ok(gear.some(d=>d.reqLevel===lvl),cls+' lvl '+lvl)}});
test('mage hunter and ranger can equip their generated offhands',()=>run(`for(const cls of ['mage','hunter','ranger']){state.player.class=cls;const d=Object.values(ITEMS).find(x=>x.classGear&&x.classes?.includes(cls)&&x.slot==='offhand'&&x.reqLevel===12);assert.ok(d);state.player.level=20;const inst=createGearInstance(d.id);state.player.inventory.push(inst);assert.equal(itemCanGoToSlot(inst,'offhand'),true)}`));
test('generated class gear perks are visible to combat perk system',()=>run(`state.player.class='ranger';state.player.level=20;const d=Object.values(ITEMS).find(x=>x.classGear&&x.classes?.includes('ranger')&&x.slot==='helmet'&&x.reqLevel===12);const inst=createGearInstance(d.id);state.player.inventory.push(inst);state.player.equipped.helmet=inst;assert.ok(itemCombatPerk(d.id));assert.ok(equippedCombatPerks().poisonAmp>0);`));


test('selected loot with no space stays pending',()=>{ctx.document.querySelectorAll=()=>[{dataset:{battleLoot:'0'}}];run(`state.player.inventoryCapacity=inventoryUsedSlots();battleResult={xp:5,gold:2,drops:[{id:'shortSword',qty:1}]};const before=JSON.stringify(state.player);finishBattleResult(battleResult,true);assert.ok(battleResult);assert.equal(JSON.stringify(state.player),before);`)});
test('loot can be collected only once',()=>{ctx.document.querySelectorAll=()=>[{dataset:{battleLoot:'0'}}];run(`battleResult={xp:5,gold:2,drops:[{id:'potion',qty:2}]};const result=battleResult,q=countItem('potion');finishBattleResult(result,true);finishBattleResult(result,true);assert.equal(countItem('potion'),q+2);assert.equal(battleResult,null);`)});
