test('cannot sell equipped item',()=>run(`const i=state.player.inventory.findIndex(x=>x.uid===state.player.equipped.weapon.uid),before=JSON.stringify(state.player);sellIndex(i);assert.equal(JSON.stringify(state.player),before);`));
test('salvage preserves gear when outputs do not fit',()=>run(`state.player.inventory=state.player.inventory.filter(i=>i.id!=='scrap');const i=createGearInstance('stormCrown');state.player.inventory.push(i);state.player.inventoryCapacity=inventoryUsedSlots();const before=JSON.stringify(state.player);salvageIndex(state.player.inventory.length-1);assert.equal(JSON.stringify(state.player),before);`));
test('legacy 3.8 save keeps gold, gear and quest history',()=>run(`const old=JSON.parse(JSON.stringify(state));old.version=380;old.player.gold=777;old.quests.done=['q1','q2'];old.settings.demo=true;const migrated=normalizeState(old);assert.equal(migrated.version,394);assert.equal(migrated.player.gold,777);assert.equal(migrated.quests.done.join(','),'q1,q2');assert.equal(migrated.settings.demo,false);assert.ok(migrated.player.equipped.weapon.uid);`));
test('damaged session is rejected by import validation',()=>run(`assert.throws(()=>validateSessionSave({session:{combat:{}}}));assert.throws(()=>validateSessionSave({session:{dungeonRun:{id:DUNGEONS[0].id,size:8,grid:[]}}}));`));
test('save storage error is reported without crashing',()=>{const set=ctx.localStorage.setItem;ctx.localStorage.setItem=()=>{throw new Error('quota')};run(`assert.doesNotThrow(()=>save());assert.equal(save.failed,true);`);ctx.localStorage.setItem=set});
test('old delayed callback cannot attack in a new fight',()=>{run(`startCombat({id:'old',template:'slime',type:'monster',synthetic:true,variant:'normal'});queueEnemyTurn(1100);`);const cb=callbacks.find(x=>x.delay===1100);run(`combat=null;startCombat({id:'new',template:'rat',type:'monster',synthetic:true,variant:'normal'});queueEnemyTurn(1100);`);cb.fn();run(`assert.equal(combat.phase,'enemyDelay');assert.equal(combat.enemyTurns,0);`)});
test('resumed pending enemy turn runs exactly once',()=>{run(`startCombat({id:'test',template:'slime',type:'monster',synthetic:true,variant:'normal'});queueEnemyTurn();state=JSON.parse(localStorage.getItem(SAVE_KEY));restoreSession();resumeSession();`);const cb=callbacks.filter(x=>x.delay===350).at(-1);assert.ok(cb);cb.fn();const hp=run('state.player.hp');cb.fn();assert.equal(run('state.player.hp'),hp);run(`assert.equal(combat.phase,'enemyResult');`)});

test('all monsters have a valid map size and insects are smaller than wolves and demons',()=>run(`for(const m of MONSTERS){const size=monsterMapSize(m);assert.ok(size.width>=38&&size.height>=38&&size.width<=100&&size.height<=100)}assert.ok(monsterMapSize(MONSTERS.find(m=>m.id==='beetle')).height<monsterMapSize(MONSTERS.find(m=>m.id==='wolf')).height);assert.ok(monsterMapSize(MONSTERS.find(m=>m.id==='wolf')).height<monsterMapSize(MONSTERS.find(m=>m.id==='demon')).height);`));
