test('drawer includes gear, bag grid, three tabs and character resources',()=>run(`const html=gearDrawerHTML();assert.ok(html.includes('drawer-equipment'));assert.ok(html.includes('drawer-bag-grid'));assert.ok(html.includes('data-drawer-tab="quests"'));assert.ok(html.includes('data-drawer-tab="stats"'));assert.ok(html.includes('data-drawer-tab="bag"'));assert.ok(html.includes('Mana'));`));
test('drawer filters consumables and materials without losing inventory',()=>run(`const before=JSON.stringify(state.player.inventory);const usable=drawerInventoryEntries('usable');assert.ok(usable.some(e=>e.item.id==='potion'));assert.ok(usable.every(e=>['consumable','ammo'].includes(itemDef(e.item.id).type)));assert.ok(drawerInventoryEntries('materials').some(e=>e.item.id==='herb'));assert.equal(JSON.stringify(state.player.inventory),before);`));
