test('backpack item can be moved into an empty slot and position persists',()=>run(`const first=backpackEntries()[0],item=first.item;assert.ok(moveBackpackItemToSlot(first.index,10));assert.equal(item.bagSlot,10);assert.equal(backpackEntries().find(e=>e.item===item).slot,10);`));
