test('pagehide save cannot overwrite destination slot during character switch',()=>run(`SAVE_KEY=REAL_SAVE_KEY;characterSlotTransition=false;for(let i=1;i<=CHARACTER_LIMIT;i++)localStorage.removeItem(characterSlotKey(i,'gps'));localStorage.removeItem(CHARACTER_META_REAL);setActiveCharacterSlot(1);state=normalizeState(${base});state.player.name='Pierwszy';state.created=111;save();const two=normalizeState(${base});two.player.name='Drugi';two.player.class='mage';two.created=222;localStorage.setItem(characterSlotKey(2,'gps'),JSON.stringify(two));switchCharacterSlot(2);assert.equal(activeCharacterSlot(),2);assert.equal(state.player.name,'Drugi');save();assert.equal(JSON.parse(localStorage.getItem(characterSlotKey(1,'gps'))).player.name,'Pierwszy');assert.equal(JSON.parse(localStorage.getItem(characterSlotKey(2,'gps'))).player.name,'Drugi');characterSlotTransition=false;`));
test('registry cleanup frees duplicate slot created by old overwrite bug',()=>run(`SAVE_KEY=REAL_SAVE_KEY;characterSlotTransition=false;for(let i=1;i<=CHARACTER_LIMIT;i++)localStorage.removeItem(characterSlotKey(i,'gps'));const same=normalizeState(${base});same.player.name='Duplikat';same.created=999;localStorage.setItem(characterSlotKey(1,'gps'),JSON.stringify(same));localStorage.setItem(characterSlotKey(2,'gps'),JSON.stringify(same));setActiveCharacterSlot(2);repairCharacterRegistry();assert.equal(rawLoad(characterSlotKey(1,'gps')),null);assert.equal(rawLoad(characterSlotKey(2,'gps')).player.name,'Duplikat');`));
console.log(`${count} regression checks passed including 3.9.7.7 character switch race fix.`);

