test('all potion tiers are available in combat and recipe licenses are finite',()=>run(`for(const amount of [50,100,150,200]){assert.ok(ALCHEMY_READY_STOCK.some(x=>itemDef(x.id).heal===amount));assert.ok(ALCHEMY_READY_STOCK.some(x=>itemDef(x.id).mana===amount))}state.player.inventory.push({id:'potion200',qty:1},{id:'manaPotion200',qty:1});startCombat({id:'test',template:'slime',type:'monster',synthetic:true,variant:'normal',elite:false});combat.menu='heal';originalOpenCombat();assert.ok(app.innerHTML.includes('data-combat-potion="potion200"'));assert.ok(app.innerHTML.includes('data-combat-potion="manaPotion200"'));combat=null;state.player.gold=1000;buyAlchemyRecipe('potion200');assert.equal(alchemyRecipeUses('potion200'),ALCHEMY_RECIPE_OFFERS.potion200.uses+guildAlchemyExtraUses());`));
test('offline regeneration restores health mana and stamina once after an hour',()=>run(`state.player.hp=1;state.player.mana=0;state.player.stamina=0;state.regen={lastAt:Date.now()-3600000,hpCarry:0,manaCarry:0,staminaCarry:0};const now=Date.now();assert.equal(applyPassiveRegen(now),true);assert.ok(state.player.hp>1);assert.equal(state.player.mana,state.player.maxMana);assert.equal(state.player.stamina,20);const old=state.player.hp;assert.equal(applyPassiveRegen(now),false);assert.equal(state.player.hp,old);`));
test('every named monster has a loot table and gear does not exceed its rank',()=>run(`const caps={'Zwykły':2,'Elita':3,'Heros':4,'Legenda':5},ranks=['common','uncommon','rare','epic','heroic','legendary'];for(const m of MONSTERS){const rows=monsterLootTable(m.id);assert.ok(rows.length,m.id);for(const r of rows){assert.ok(ITEMS[r.id],r.id);if(ITEMS[r.id].slot)assert.ok(ranks.indexOf(ITEMS[r.id].rarity)<=caps[m.rank],m.id+' '+r.id)}}`));
test('legendary boss bonus gear comes from its visible named loot table',()=>run(`state.player.level=100;state.player.class='knight';state.tutorial.complete=true;state.tutorial.rewardGiven=true;const m=MONSTERS.find(x=>x.id==='stormDrake');for(let n=0;n<30;n++){const result=rollCombatLoot(m,{elite:false},{isBoss:true});for(const d of result.drops.filter(x=>ITEMS[x.id].slot))assert.ok(monsterLootTable(m.id).some(r=>r.id===d.id),d.id)}`));
test('equipment attributes affect combat calculations while ordinary items remain plain',()=>run(`const plain=Object.values(ITEMS).find(d=>d.slot&&!['str','agi','int','vit','lck'].some(k=>d[k]));assert.ok(plain);state.player.class='knight';state.player.level=100;const boosted=Object.values(ITEMS).find(d=>d.slot==='weapon'&&itemClassAllowed(d)&&d.str>0);assert.ok(boosted);const old=primaryCombatStat();const inst=createGearInstance(boosted.id);state.player.inventory.push(inst);assert.ok(equipIndexToSlot(state.player.inventory.length-1,'weapon'));assert.ok(primaryCombatStat()>old);`));
test('reopening a merchant service retains its scroll position',()=>run(`state.city.placed=true;state.player.position={x:0,y:0,gps:true,accuracy:5,receivedAt:Date.now()};gpsWatch=1;const modal=document.querySelector('.modal');modal.scrollTop=264;openModal=()=>{modal.scrollTop=0};originalOpenBuilding('alchemist','service');assert.equal(modal.scrollTop,264);`));
