test('biome shapes have varied edges and weights are not fixed area quotas',()=>run(`const s=biomeSite(-1,0),pts=biomeOutline(s);assert.equal(pts.length,64);assert.ok(biomeContains(s,s.x,s.y));assert.ok(new Set(pts.map(p=>Math.round(Math.hypot((p.x-s.x)/s.rx,(p.y-s.y)/s.ry)*100))).size>5);assert.equal(Object.values(BIOMES).reduce((n,b)=>n+b.weight,0),100);assert.equal(BIOMES.ruins.weight,5);assert.equal(biomeAt(0,0),'meadow');`));
