test('city has a mapped 180 metre radius and mobile services need current GPS',()=>run(`assert.equal(CITY_RADIUS,180);state.city.placed=true;state.player.position={x:181,y:0,gps:true,accuracy:5,receivedAt:Date.now()};gpsWatch=1;assert.equal(insideCity(),false);assert.equal(cityServiceAccess(),false);state.player.position.x=179;assert.equal(cityServiceAccess(),true);state.player.position.receivedAt=Date.now()-60000;assert.equal(cityServiceAccess(),false);`));
