test('placed city keeps local monster spawns outside the city zone',()=>run(`state.city.placed=true;state.city.x=350;state.city.y=350;const monsters=generateLivingMonsters(daySeed(),{x:350,y:350},state);assert.ok(monsters.length);assert.ok(monsters.every(e=>dist(e,state.city)>CITY_RADIUS));`));
test('old saves refresh local shrines without losing player progress',()=>run(`const old=JSON.parse(JSON.stringify(state));old.version=392;old.player.gold=177;old.world.entities=old.world.entities.filter(e=>e.type!=='shrine');const migrated=normalizeState(old);assert.equal(migrated.player.gold,177);assert.ok(migrated.world.entities.some(e=>e.type==='shrine'));`));
test('heads heals fully and consumes one coin and the daily attempt across reload',()=>run(`const e=state.world.entities.find(e=>e.type==='shrine');assert.ok(e);state.player.position={x:e.x,y:e.y,gps:true,accuracy:5,receivedAt:Date.now()};gpsWatch=1;state.player.hp=4;const gold=state.player.gold;flipShrineCoin(e.id,.2);assert.equal(state.player.hp,state.player.maxHp);assert.equal(state.player.gold,gold-1);assert.equal(shrineVisit(e.id).result,'heads');flipShrineCoin(e.id,.8);assert.equal(state.player.gold,gold-1);state=normalizeState(JSON.parse(JSON.stringify(state)));assert.equal(shrineVisit(e.id).result,'heads');`));
test('tails never heals and each shrine has its own daily attempt',()=>run(`const e=state.world.entities.find(e=>e.type==='shrine');state.player.position={x:e.x,y:e.y,gps:true,accuracy:5,receivedAt:Date.now()};gpsWatch=1;state.player.hp=7;const gold=state.player.gold;flipShrineCoin(e.id,.8);assert.equal(state.player.hp,7);assert.equal(state.player.gold,gold-1);assert.equal(shrineVisit(e.id).result,'tails');const second={...e,id:'shrine_second'};state.world.entities.push(second);flipShrineCoin(second.id,.2);assert.equal(state.player.hp,state.player.maxHp);assert.equal(state.player.gold,gold-2);assert.equal(shrineVisit(second.id).result,'heads');`));
