test('guild contracts can be accepted progressed claimed once and resumed from save',()=>run(`state.player.guild='Bractwo';ensureSocialState();const g=guildState(),c=g.contracts[0];assert.ok(c);acceptGuildContract(c.id);for(let i=0;i<c.need;i++)progressGuildContracts(c.target);assert.equal(c.progress,c.need);const gold=state.player.gold,rep=state.adventure.reputation;claimGuildContract(c.id);assert.equal(state.player.gold,gold+c.gold);assert.equal(state.adventure.reputation,rep+c.rep);claimGuildContract(c.id);assert.equal(state.player.gold,gold+c.gold);state=normalizeState(JSON.parse(localStorage.getItem(SAVE_KEY)));assert.equal(guildState().contracts.find(x=>x.id===c.id).claimed,true);`));
test('accepted guild contracts remain after daily proposals refresh',()=>run(`state.player.guild='Bractwo';ensureSocialState();const g=guildState(),c=g.contracts[0];acceptGuildContract(c.id);progressGuildContracts(c.target);g.contractDay=daySeed()-1;ensureSocialState();const carried=g.contracts.find(x=>x.id===c.id);assert.ok(carried);assert.equal(carried.progress,1);assert.equal(carried.accepted,true);`));
test('guild material board moves delivered loot into a local warehouse exactly once',()=>run(`state.player.guild='Bractwo';ensureSocialState();postGuildRequest('wolfPelt',3);const g=guildState(),r=g.requests[0];assert.equal(r.goal,3);acceptGuildRequest(r.id);addItem('wolfPelt',3);const before=countItem('wolfPelt');deliverGuildRequest(r.id);assert.equal(countItem('wolfPelt'),before-3);assert.equal(r.delivered,3);assert.equal(g.warehouse.wolfPelt,3);deliverGuildRequest(r.id);assert.equal(g.warehouse.wolfPelt,3);assert.equal(r.completed,true);state=normalizeState(JSON.parse(localStorage.getItem(SAVE_KEY)));assert.equal(guildState().warehouse.wolfPelt,3);`));
test('plain class stock and blacksmith stock cover every class at the regular tier',()=>run(`for(const cls of Object.keys(CLASSES)){state.player.class=cls;state.player.level=40;const basics=shopInventoryPages()[2].map(itemDef);assert.ok(basics.some(d=>d.slot==='weapon'&&d.merchantPlain&&d.classes.includes(cls)),cls);assert.ok(basics.some(d=>d.slot==='armor'&&d.merchantPlain&&d.classes.includes(cls)),cls);assert.ok(basics.filter(d=>d.merchantPlain).every(d=>!['str','agi','int','vit','lck'].some(k=>d[k])),cls);const smith=smithStockIds().map(itemDef);assert.ok(smith.some(d=>d.slot==='weapon'&&d.classes.includes(cls)),cls);assert.ok(smith.every(d=>['common','uncommon','rare'].includes(d.rarity)&&!d.bossUnique),cls)}`));
test('one smith gear purchase depletes stock until the next six hour cycle',()=>run(`state.player.level=40;state.player.gold=10000;const id=smithStockIds()[0],price=smithOfferPrice(id),before=state.player.inventory.filter(i=>i.id===id).length;assert.ok(id);buyItem(id,'smith',1);assert.equal(state.player.gold,10000-price);assert.equal(state.player.inventory.filter(i=>i.id===id).length,before+1);assert.equal(merchantSoldOut(id,'smith'),true);buyItem(id,'smith',1);assert.equal(state.player.inventory.filter(i=>i.id===id).length,before+1);state.economy.merchantCycle=merchantCycle()-1;ensureMerchantStockState();assert.equal(merchantSoldOut(id,'smith'),false);`));
test('shop gear sells once per delivery while ordinary potions remain repeatable',()=>run(`state.player.level=40;state.player.gold=10000;const id=shopInventoryPages()[2].find(x=>itemDef(x).merchantPlain),before=state.player.inventory.filter(i=>i.id===id).length;assert.ok(id);buyItem(id,'shop',merchantBuyPrice(id));assert.equal(merchantSoldOut(id,'shop'),true);buyItem(id,'shop',merchantBuyPrice(id));assert.equal(state.player.inventory.filter(i=>i.id===id).length,before+1);const q=countItem('potion');buyItem('potion','shop',merchantBuyPrice('potion'));buyItem('potion','shop',merchantBuyPrice('potion'));assert.equal(countItem('potion'),q+2);`));
test('auction vendor offers daily class gear without unique boss loot and limits purchase',()=>run(`state.player.level=40;state.player.gold=10000;const ids=auctionOfferIds();assert.ok(ids.length);assert.ok(ids.length<=8);for(const id of ids){const d=itemDef(id);assert.ok(['uncommon','rare'].includes(d.rarity));assert.ok(itemClassAllowed(d)&&!d.bossUnique&&!d.classGear)}const id=ids[0],before=state.player.inventory.filter(i=>i.id===id).length;buyItem(id,'auction',1);assert.ok(ensureAuctionVendorState().includes(id));buyItem(id,'auction',1);assert.equal(state.player.inventory.filter(i=>i.id===id).length,before+1);const html=auctionHTML();assert.ok(html.includes('data-auction-search'));assert.ok(html.includes('data-auction-slot'));assert.ok(html.includes('Wyprzedane'));`));
test('alchemy and smith recipes explain where their ingredients can be found',()=>run(`const alchemy=RECIPES.find(r=>r.station==='alchemist'&&Object.keys(r.ingredients).length);const smith=RECIPES.find(r=>r.station==='smith'&&Object.keys(r.ingredients).length);assert.ok(ingredientSourcesHTML(alchemy).includes('Gdzie zdobyć składniki'));assert.ok(recipeCardHTML(smith,'Wykuj').includes('Gdzie zdobyć składniki'));assert.ok(materialSourceLabel('wolfPelt').includes('Łup:'));`));
test('every recipe ingredient has a reachable drop, merchant stock or ingredient recipe',()=>run(`const accessible=new Set(['runeShard','ancientRelic']);for(const m of MONSTERS)for(const row of monsterLootTable(m.id))accessible.add(row.id);for(const cls of Object.keys(CLASSES)){state.player.class=cls;for(const id of shopInventoryPages()[3])accessible.add(id)}for(const row of ALCHEMY_READY_STOCK)accessible.add(row.id);let changed=true;while(changed){changed=false;for(const r of RECIPES)if(Object.keys(r.ingredients).every(id=>accessible.has(id))&&!accessible.has(r.result)){accessible.add(r.result);changed=true}}for(const r of RECIPES)for(const id of Object.keys(r.ingredients))assert.ok(accessible.has(id),r.id+' requires unreachable '+id);`));
